//! Core-only scripted wire tests. Bytes are deliberately opaque: the host is a stand-in here;
//! real video is generated by MediaRecorder in the separate Main/Electron acceptance tests.
#![allow(clippy::unwrap_used)]
use super::*;
use aura_agent_domain::*;
use aura_ipc::WireFrame;
use base64::Engine as _;
mod sequence;
mod sources;
mod wire;

const SOURCE: &[u8] = b"opaque source; Core transports, the stand-in host decodes";
const JPEG: &str = "/9j/4AAQSkZJRg==";

fn services(runtime: &crate::RuntimeState) -> &crate::RuntimeServices {
    let crate::StartupMode::Ready(services) = &runtime.startup_mode else { panic!("ready") };
    services
}

async fn images(runtime: &crate::RuntimeState, model: ModelProfileId, on: bool) {
    let revision = crate::r03_tests::success(runtime, "models.settings.get_snapshot", json!({}))
        .await["models_revision"]
        .clone();
    crate::r03_tests::success(
        runtime,
        "models.profile.update",
        json!({"expected_revision":revision,
        "model_profile_id":model,"display_name":"Media fixture","notes":null,"enabled":true,
        "request_defaults":{"max_output_tokens":4096,"temperature":null,"top_p":null,
            "chat_output_token_field":null,"chat_instruction_role":null,"image_input":on},
        "historical_snapshot_max_tokens":1024}),
    )
    .await;
}

fn frame() -> MediaImageV1 {
    MediaImageV1 {
        media_type: "image/jpeg".into(),
        data_base64: JPEG.into(),
        width: 32,
        height: 24,
    }
}

fn play_host(
    runtime: &crate::RuntimeState,
) -> (Arc<Mutex<Vec<MediaHostCommandV1>>>, tokio::task::JoinHandle<()>) {
    let bridge = services(runtime).agent_required().media();
    let queue = crate::AsyncPriorityQueue::new();
    bridge.pin_publisher(queue.clone());
    let seen = Arc::new(Mutex::new(vec![]));
    let recorded = Arc::clone(&seen);
    let task = tokio::spawn(async move {
        while let Ok(outbound) = queue.recv().await {
            let WireFrame::Control(bytes) = outbound.frame else { continue };
            let notice: crate::JsonRpcNotification = serde_json::from_slice(&bytes).unwrap();
            if notice.method != "media.command.v1" {
                continue;
            }
            let command: MediaHostCommandV1 = serde_json::from_value(notice.params).unwrap();
            recorded.lock().unwrap().push(command.clone());
            let read = bridge
                .read(&MediaHostReadRequestV1 {
                    command_id: command.command_id.clone(),
                    runtime_instance_id: command.runtime_instance_id,
                    session_id: command.session_id,
                    offset: 0,
                    length: command.file_size as u32,
                })
                .unwrap();
            assert_eq!(
                base64::engine::general_purpose::STANDARD.decode(read.data_base64).unwrap(),
                SOURCE
            );
            let result = match &command.action {
                MediaHostActionV1::Probe => MediaHostCompletedV1::Probe(MediaProbeResult {
                    duration: 2.0,
                    width: 32,
                    height: 24,
                    frame_rate: Some(25.0),
                    has_audio: Some(false),
                    container: Some("webm".into()),
                    codec: None,
                    byte_length: command.file_size,
                }),
                MediaHostActionV1::Frames { times, count, sheet, .. } => {
                    let times = times.clone().unwrap_or_else(|| {
                        (0..count.unwrap())
                            .map(|i| 2.0 * (f64::from(i) + 0.5) / f64::from(count.unwrap()))
                            .collect()
                    });
                    MediaHostCompletedV1::Frames(MediaFramesHostResultV1 {
                        frames: times
                            .into_iter()
                            .map(|time| MediaHostFrameV1 {
                                requested_time: time,
                                actual_time: time,
                                image: (!sheet).then(frame),
                            })
                            .collect(),
                        sheet: sheet.then(frame),
                    })
                }
            };
            assert!(bridge.complete(MediaHostResultV1 {
                command_id: command.command_id,
                runtime_instance_id: command.runtime_instance_id,
                session_id: command.session_id,
                outcome: MediaHostOutcomeV1::Completed { result }
            }));
        }
    });
    (seen, task)
}

async fn finish(runtime: &crate::RuntimeState, started: &AgentRunProjection) {
    let request = AgentRunRequest {
        session_id: started.turn.session_id,
        agent_run_id: started.run.agent_run_id,
    };
    let done = wait(runtime, &request, |view| view.turn.state.terminal()).await;
    assert!(matches!(done.turn.state, TurnTaskState::Completed { .. }), "{done:?}");
}

fn scenario(tool: &'static str, arguments: Value) -> Scenario {
    Scenario::Browser {
        tool,
        arguments: Box::leak(serde_json::to_string(&arguments).unwrap().into_boxed_str()),
    }
}

fn tool_text(provider: &Provider) -> String {
    provider
        .requests
        .lock()
        .unwrap()
        .iter()
        .flat_map(|request| request["messages"].as_array().into_iter().flatten())
        .filter(|message| message["role"] == "tool")
        .filter_map(|message| message["content"].as_str())
        .collect::<Vec<_>>()
        .join("\n")
}
